R["apc-m11-binsearch"] = "public class Solution {\n    public static int binarySearch(int[] arr, int target) {\n        int lo = 0;\n        int hi = arr.length - 1;\n        while (lo <= hi) {\n            int mid = (lo + hi) / 2;\n            if (arr[mid] == target) {\n                return mid;\n            } else if (arr[mid] < target) {\n                lo = mid + 1;\n            } else {\n                hi = mid - 1;\n            }\n        }\n        return -1;\n    }\n}\n";
W["apc-m11-binsearch"] = "public class Solution {\n    public static int binarySearch(int[] arr, int target) {\n        // BUG: moves lo on the wrong branch, walks off the array end\n        int lo = 0;\n        int hi = arr.length - 1;\n        while (lo <= hi) {\n            int mid = (lo + hi) / 2;\n            if (arr[mid] == target) {\n                return mid;\n            } else if (arr[mid] < target) {\n                lo = mid;\n            } else {\n                hi = mid;\n            }\n        }\n        return -1;\n    }\n}\n";
