R["apc-cp-m11-sortkeys"] = "public class Solution {\n    public static int[] sortNames(int[] keys) {\n        int[] out = new int[keys.length];\n        for (int i = 0; i < keys.length; i++) {\n            out[i] = keys[i];\n        }\n        for (int i = 1; i < out.length; i++) {\n            int key = out[i];\n            int j = i - 1;\n            while (j >= 0 && out[j] % 10 > key % 10) {\n                out[j + 1] = out[j];\n                j--;\n            }\n            out[j + 1] = key;\n        }\n        return out;\n    }\n}\n";
W["apc-cp-m11-sortkeys"] = "public class Solution {\n    public static int[] sortNames(int[] keys) {\n        // BUG: unstable tie handling \u2014 equal keys come out reversed\n        int[] out = new int[keys.length];\n        for (int i = 0; i < keys.length; i++) {\n            out[i] = keys[i];\n        }\n        for (int i = 1; i < out.length; i++) {\n            int key = out[i];\n            int j = i - 1;\n            while (j >= 0 && out[j] % 10 >= key % 10) {\n                out[j + 1] = out[j];\n                j--;\n            }\n            out[j + 1] = key;\n        }\n        return out;\n    }\n}\n";
