R["apc-m12-fix-register"] = "public class Solution {\n    public static class Register {\n        private int items;\n        private int total;\n\n        public Register() {\n            items = 0;\n            total = 0;\n        }\n\n        public void scan(int price) {\n            total = total + price;\n            items++;\n        }\n\n        public void undo(int price) {\n            if (items == 0) {\n                return;\n            }\n            total = total - price;\n            items--;\n        }\n\n        public int total() {\n            return total;\n        }\n\n        public int items() {\n            return items;\n        }\n    }\n}\n";
