R["apc-cp-m12-locker"] = "public class Solution {\n    public static class Locker {\n        private String[] contents;\n        private int size;\n\n        public Locker(int capacity) {\n            contents = new String[capacity];\n            size = 0;\n        }\n\n        public boolean add(String item) {\n            if (size >= contents.length) {\n                return false;\n            }\n            contents[size] = item;\n            size++;\n            return true;\n        }\n\n        public boolean remove(String item) {\n            for (int i = 0; i < size; i++) {\n                if (contents[i].equals(item)) {\n                    contents[i] = null;\n                    for (int j = i; j < size - 1; j++) {\n                        contents[j] = contents[j + 1];\n                    }\n                    contents[size - 1] = null;\n                    size--;\n                    return true;\n                }\n            }\n            return false;\n        }\n\n        public int count() {\n            return size;\n        }\n\n        public boolean isFull() {\n            return size == contents.length;\n        }\n    }\n}\n";
W["apc-cp-m12-locker"] = "public class Solution {\n    public static class Locker {\n        // BUG: size tracks total adds, not occupied slots \u2014 count drifts up\n        private String[] contents;\n        private int size;\n\n        public Locker(int capacity) {\n            contents = new String[capacity];\n            size = 0;\n        }\n\n        public boolean add(String item) {\n            if (size >= contents.length) {\n                return false;\n            }\n            for (int i = 0; i < contents.length; i++) {\n                if (contents[i] == null) {\n                    contents[i] = item;\n                    size++;\n                    return true;\n                }\n            }\n            return false;\n        }\n\n        public boolean remove(String item) {\n            for (int i = 0; i < contents.length; i++) {\n                if (contents[i] != null && contents[i].equals(item)) {\n                    contents[i] = null;\n                    return true;\n                }\n            }\n            return false;\n        }\n\n        public int count() {\n            return size;\n        }\n\n        public boolean isFull() {\n            return size == contents.length;\n        }\n    }\n}\n";
