R["apc-m14-palindrome"] = "public class Solution {\n    public static boolean isPal(String s, int lo, int hi) {\n        if (lo >= hi) {\n            return true;\n        }\n        if (s.charAt(lo) != s.charAt(hi)) {\n            return false;\n        }\n        return isPal(s, lo + 1, hi - 1);\n    }\n}\n";
