R["apc-cp-m14-countchar"] = "public class Solution {\n    public static int countChar(String s, char c, int i) {\n        if (i == s.length()) {\n            return 0;\n        }\n        int hit = (s.charAt(i) == c) ? 1 : 0;\n        return hit + countChar(s, c, i + 1);\n    }\n}\n";
