R["apc-m17-bsearch"] = "public class Solution {\n    public static int binarySearch(int[] sorted, int target) {\n        int lo = 0;\n        int hi = sorted.length - 1;\n        while (lo <= hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (sorted[mid] == target) {\n                return mid;\n            }\n            if (sorted[mid] < target) {\n                lo = mid + 1;\n            } else {\n                hi = mid - 1;\n            }\n        }\n        return -1;\n    }\n}\n";
W["apc-m17-bsearch"] = "public class Solution {\n    public static int binarySearch(int[] sorted, int target) {\n        // BUG: loop runs while lo < hi with hi = mid - 1 \u2014 the range\n        // collapses before the last candidate is examined, so the first\n        // and last elements are never found\n        int lo = 0;\n        int hi = sorted.length - 1;\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;\n            if (sorted[mid] == target) {\n                return mid;\n            }\n            if (sorted[mid] < target) {\n                lo = mid + 1;\n            } else {\n                hi = mid - 1;\n            }\n        }\n        return -1;\n    }\n}\n";
