W["apc-m19-topnames"] = "import java.util.*;\n\npublic class Solution {\n    public static class Song {\n        private String title;\n        private int plays;\n\n        public Song(String title, int plays) {\n            this.title = title;\n            this.plays = plays;\n        }\n\n        public String getTitle() {\n            return title;\n        }\n\n        public int getPlays() {\n            return plays;\n        }\n    }\n\n    public static ArrayList<String> topNames(ArrayList<Song> list, int cut) {\n        // BUG: adds the whole Song object instead of the title \u2014 type\n        // mismatch with the ArrayList<String> contract\n        ArrayList<String> names = new ArrayList<String>();\n        for (Song s : list) {\n            if (s.getPlays() >= cut) {\n                names.add(s.getTitle().toUpperCase());\n            }\n        }\n        return names;\n    }\n}\n";
R["apc-m19-register"] = "import java.util.*;\n\npublic class Solution {\n    public static class Register {\n        private int cents;\n\n        public Register() {\n            cents = 0;\n        }\n\n        public void add(int c) {\n            cents += c;\n        }\n\n        public boolean spend(int c) {\n            if (c > cents) {\n                return false;\n            }\n            cents -= c;\n            return true;\n        }\n\n        public int balance() {\n            return cents;\n        }\n    }\n}\n";
W["apc-m19-register"] = "import java.util.*;\n\npublic class Solution {\n    public static class Register {\n        private int cents;\n\n        public Register() {\n            cents = 0;\n        }\n\n        public void add(int c) {\n            cents += c;\n        }\n\n        public boolean spend(int c) {\n            // BUG: subtracts unconditionally \u2014 the empty register\n            // goes negative and wrongly reports success\n            cents -= c;\n            return true;\n        }\n\n        public int balance() {\n            return cents;\n        }\n    }\n}\n";
R["apc-m19-positives"] = "import java.util.*;\n\npublic class Solution {\n    public static ArrayList<Integer> positives(int[] a) {\n        ArrayList<Integer> out = new ArrayList<Integer>();\n        for (int x : a) {\n            if (x > 0) {\n                out.add(x);\n            }\n        }\n        return out;\n    }\n}\n";
W["apc-m19-positives"] = "import java.util.*;\n\npublic class Solution {\n    public static ArrayList<Integer> positives(int[] a) {\n        // BUG: uses >= 0 so zero sneaks into the \"positives\" list\n        ArrayList<Integer> out = new ArrayList<Integer>();\n        for (int x : a) {\n            if (x >= 0) {\n                out.add(x);\n            }\n        }\n        return out;\n    }\n}\n";
R["apc-m19-fix-removeall"] = "import java.util.*;\n\npublic class Solution {\n    public static void removeAll(ArrayList<Integer> list, int value) {\n        for (int i = list.size() - 1; i >= 0; i--) {\n            if (list.get(i).intValue() == value) {\n                list.remove(i);\n            }\n        }\n    }\n}\n";
W["apc-m19-fix-removeall"] = "import java.util.*;\n\npublic class Solution {\n    public static void removeAll(ArrayList<Integer> list, int value) {\n        // BUG: original flaw kept \u2014 forward removal skips the element\n        // after each removed one\n        for (int i = 0; i < list.size(); i++) {\n            if (list.get(i).intValue() == value) {\n                list.remove(i);\n            }\n        }\n    }\n}\n";
R["apc-cp-m19-log"] = "import java.util.*;\n\npublic class Solution {\n    public static class Log {\n        private int total;\n        private int count;\n\n        public Log() {\n            total = 0;\n            count = 0;\n        }\n\n        public void record(int reading) {\n            total += reading;\n            count++;\n        }\n\n        public int average() {\n            if (count == 0) {\n                return 0;\n            }\n            return total / count;\n        }\n\n        public int getCount() {\n            return count;\n        }\n    }\n}\n";
W["apc-cp-m19-log"] = "import java.util.*;\n\npublic class Solution {\n    public static class Log {\n        private int total;\n        private int count;\n\n        public Log() {\n            total = 0;\n            count = 0;\n        }\n\n        public void record(int reading) {\n            total += reading;\n            count++;\n        }\n\n        public int average() {\n            // BUG: no empty-log guard \u2014 divides by zero count\n            return total / count;\n        }\n\n        public int getCount() {\n            return count;\n        }\n    }\n}\n";
R["apc-m20-shelf"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Book {\n        private String title;\n        private int pages;\n\n        public Book(String title, int pages) {\n            this.title = title;\n            this.pages = pages;\n        }\n\n        public String getTitle() {\n            return title;\n        }\n\n        public int getPages() {\n            return pages;\n        }\n    }\n\n    public static int shelfPages(ArrayList<Book> shelf, int limit) {\n        int total = 0;\n        for (Book b : shelf) {\n            if (b.getPages() <= limit) {\n                total += b.getPages();\n            }\n        }\n        return total;\n    }\n}\n";
W["apc-m20-shelf"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Book {\n        private String title;\n        private int pages;\n\n        public Book(String title, int pages) {\n            this.title = title;\n            this.pages = pages;\n        }\n\n        public String getTitle() {\n            return title;\n        }\n\n        public int getPages() {\n            return pages;\n        }\n    }\n\n    public static int shelfPages(ArrayList<Book> shelf, int limit) {\n        // BUG: compares against the wrong bound \u2014 strictly-less\n        // excludes exactly-at-limit books the spec includes\n        int total = 0;\n        for (Book b : shelf) {\n            if (b.getPages() < limit) {\n                total += b.getPages();\n            }\n        }\n        return total;\n    }\n}\n";
R["apc-m20-fix-meter"] = "public class Solution {\n    public static class Meter {\n        private int units;\n        private int cap;\n\n        public Meter(int cap) {\n            this.cap = cap;\n            this.units = 0;\n        }\n\n        public void tick() {\n            if (units < cap) {\n                units++;\n            }\n        }\n\n        public boolean overflowed() {\n            return units == cap;\n        }\n    }\n}\n";
W["apc-m20-fix-meter"] = "public class Solution {\n    public static class Meter {\n        private int units;\n        private int cap;\n\n        public Meter(int cap) {\n            this.cap = cap;\n            this.units = 0;\n        }\n\n        public void tick() {\n            // BUG: original flaw kept \u2014 ticks past the cap, so\n            // overflowed() (units == cap) can never become true\n            units++;\n        }\n\n        public boolean overflowed() {\n            return units == cap;\n        }\n    }\n}\n";
R["apc-m20-bank"] = "public class Solution {\n    public static class Account {\n        private int balance;\n\n        public Account(int opening) {\n            balance = opening;\n        }\n\n        public int getBalance() {\n            return balance;\n        }\n\n        public int deposit(int amount) {\n            if (amount > 0) {\n                balance += amount;\n            }\n            return balance;\n        }\n\n        public boolean withdraw(int amount) {\n            if (amount <= balance) {\n                balance -= amount;\n                return true;\n            }\n            return false;\n        }\n    }\n}\n";
W["apc-m20-bank"] = "public class Solution {\n    public static class Account {\n        private int balance;\n\n        public Account(int opening) {\n            balance = opening;\n        }\n\n        public int getBalance() {\n            return balance;\n        }\n\n        public int deposit(int amount) {\n            // BUG: accepts negative amounts \u2014 a \"deposit\" drains the\n            // account\n            if (amount != 0) {\n                balance += amount;\n            }\n            return balance;\n        }\n\n        public boolean withdraw(int amount) {\n            if (amount <= balance) {\n                balance -= amount;\n                return true;\n            }\n            return false;\n        }\n    }\n}\n";
R["apc-cp-m20-playlist"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Playlist {\n        private ArrayList<String> tracks;\n\n        public Playlist() {\n            tracks = new ArrayList<String>();\n        }\n\n        public void add(String title) {\n            tracks.add(title);\n        }\n\n        public boolean remove(String title) {\n            int idx = tracks.indexOf(title);\n            if (idx >= 0) {\n                tracks.remove(idx);\n                return true;\n            }\n            return false;\n        }\n\n        public int size() {\n            return tracks.size();\n        }\n    }\n}\n";
W["apc-cp-m20-playlist"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Playlist {\n        private ArrayList<String> tracks;\n\n        public Playlist() {\n            tracks = new ArrayList<String>();\n        }\n\n        public void add(String title) {\n            tracks.add(title);\n        }\n\n        public boolean remove(String title) {\n            // BUG: removes by INDEX argument even when indexOf returned\n            // -1 \u2014 drops the LAST track on an absent title\n            int idx = tracks.indexOf(title);\n            if (idx >= 0) {\n                tracks.remove(idx);\n                return true;\n            }\n            tracks.remove(tracks.size() - 1);\n            return false;\n        }\n\n        public int size() {\n            return tracks.size();\n        }\n    }\n}\n";
R["apc-m15-findcell"] = "public class Solution {\n    public static int[] find(int[][] g, int target) {\n        for (int r = 0; r < g.length; r++) {\n            for (int c = 0; c < g[0].length; c++) {\n                if (g[r][c] == target) {\n                    return new int[] {r, c};\n                }\n            }\n        }\n        return null;\n    }\n}\n";
W["apc-m15-findcell"] = "public class Solution {\n    public static int[] find(int[][] g, int target) {\n        // BUG: keeps scanning after a match \u2014 returns the LAST match,\n        // violating the first-match contract\n        int[] hit = null;\n        for (int r = 0; r < g.length; r++) {\n            for (int c = 0; c < g[0].length; c++) {\n                if (g[r][c] == target) {\n                    hit = new int[] {r, c};\n                }\n            }\n        }\n        return hit;\n    }\n}\n";
